class Counter:
    def __init__(self):
        self.i = 0
    def __iter__(self):
        return self
    def __next__(self):
        self.i += 1
        if self.i > 2:
            raise StopIteration
        return self.i
print(list(Counter()))

class Sequence:
    def __getitem__(self, index):
        if index >= 2:
            raise IndexError
        return index + 10
print(list(Sequence()))

class Bad:
    def __iter__(self):
        return [1, 2]
try:
    iter(Bad())
    print('OK')
except TypeError:
    print('TypeError')
